style.css:
@-moz-document domain("www.xiaoqiqiao.com") {
/* 重置文字样式区域，去除网页原有文字样式，但保留自己设置的关键样式 */
    body *:not(script):not(style):not(link):not(meta):not(title):not([contenteditable="true"]):not([role="presentation"]):not([aria-hidden="true"]){
        all: unset!important;
        color: #000000!important; /* 保留设置的黑色文字颜色 */
        font-family: "黑体"!important; /* 保留设置的宋体字体 */
        font-weight: normal!important; /* 保留设置的常规文字粗细 */
        letter-spacing: 1.5px!important; /* 保留设置的字间距1.5像素 */
        background-color: #ffffff!important; /* 保留设置的白色背景颜色 */
    }

    /* 元素隐藏区域 */
    /* 隐藏<span class="ant-radio"><input type="radio" class="ant-radio-input" value="A"><span class="ant-radio-inner"></span></span>结构中的特定span元素 */
    span.ant-radio span.ant-radio-inner {
        display: none!important;
    }

    /* 隐藏<span class="ant-checkbox"><input type="checkbox" class="ant-checkbox-input" value="A"><span class="ant-checkbox-inner"></span></span>结构中的特定span元素 */
    span.ant-checkbox input[type="checkbox"].ant-checkbox-input + span.ant-checkbox-inner {
        display: none!important;
    }
}
